-- RankResume PostgreSQL setup: schema plus shareable reference data only.
-- Generated from the live rankresume database. Candidate and job_description rows are intentionally excluded.
-- Run after creating the rankresume database, connected to rankresume as a role with CREATE privileges.
DO $$ BEGIN IF current_database() <> 'rankresume' THEN RAISE EXCEPTION 'Run this file only while connected to database rankresume (current database: %)', current_database(); END IF; END $$;


\restrict DBSNAoJ235Uf5suZcQNDFaELLFWuIxh4uAbj6hQ5pZ0opnODapJk9Bvjqku8Pad






CREATE TABLE public."ESCO_Skills" (
    esco_id bigint NOT NULL,
    concept_uri text,
    concept_type text,
    skill_type text,
    reuse_level text,
    preferred_label text,
    alt_labels text,
    hidden_labels text,
    status text,
    modified_date timestamp without time zone,
    scope_note text
);



CREATE SEQUENCE public."ESCO_Skills_esco_id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;



ALTER SEQUENCE public."ESCO_Skills_esco_id_seq" OWNED BY public."ESCO_Skills".esco_id;



CREATE TABLE public.candidate (
    candidate_id bigint NOT NULL,
    candidate_name character varying(150),
    email character varying(150),
    phone character varying(30),
    resume_file_name character varying(255),
    resume_hash character varying(64),
    raw_text text,
    clean_text text,
    structured_data jsonb,
    ats_score double precision,
    final_score double precision,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
);



CREATE SEQUENCE public.candidate_candidate_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;



ALTER SEQUENCE public.candidate_candidate_id_seq OWNED BY public.candidate.candidate_id;



CREATE TABLE public.job_description (
    jd_id bigint NOT NULL,
    job_title character varying(150),
    jd_file_name character varying(255),
    raw_text text,
    clean_text text,
    structured_data jsonb,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
);



CREATE SEQUENCE public.job_description_jd_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;



ALTER SEQUENCE public.job_description_jd_id_seq OWNED BY public.job_description.jd_id;



CREATE TABLE public.technology_alias (
    alias_id bigint NOT NULL,
    tech_id bigint NOT NULL,
    alias_name character varying(150) NOT NULL
);



CREATE SEQUENCE public.technology_alias_alias_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;



ALTER SEQUENCE public.technology_alias_alias_id_seq OWNED BY public.technology_alias.alias_id;



CREATE TABLE public.technology_dictionary (
    tech_id bigint NOT NULL,
    canonical_name character varying(100) NOT NULL,
    category character varying(50),
    aliases jsonb,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
);



CREATE SEQUENCE public.technology_dictionary_tech_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;



ALTER SEQUENCE public.technology_dictionary_tech_id_seq OWNED BY public.technology_dictionary.tech_id;



ALTER TABLE ONLY public."ESCO_Skills" ALTER COLUMN esco_id SET DEFAULT nextval('public."ESCO_Skills_esco_id_seq"'::regclass);



ALTER TABLE ONLY public.candidate ALTER COLUMN candidate_id SET DEFAULT nextval('public.candidate_candidate_id_seq'::regclass);



ALTER TABLE ONLY public.job_description ALTER COLUMN jd_id SET DEFAULT nextval('public.job_description_jd_id_seq'::regclass);



ALTER TABLE ONLY public.technology_alias ALTER COLUMN alias_id SET DEFAULT nextval('public.technology_alias_alias_id_seq'::regclass);



ALTER TABLE ONLY public.technology_dictionary ALTER COLUMN tech_id SET DEFAULT nextval('public.technology_dictionary_tech_id_seq'::regclass);



ALTER TABLE ONLY public."ESCO_Skills"
    ADD CONSTRAINT "ESCO_Skills_concept_uri_key" UNIQUE (concept_uri);



ALTER TABLE ONLY public."ESCO_Skills"
    ADD CONSTRAINT "ESCO_Skills_pkey" PRIMARY KEY (esco_id);



ALTER TABLE ONLY public.candidate
    ADD CONSTRAINT candidate_pkey PRIMARY KEY (candidate_id);



ALTER TABLE ONLY public.candidate
    ADD CONSTRAINT candidate_resume_hash_key UNIQUE (resume_hash);



ALTER TABLE ONLY public.job_description
    ADD CONSTRAINT job_description_pkey PRIMARY KEY (jd_id);



ALTER TABLE ONLY public.technology_alias
    ADD CONSTRAINT technology_alias_alias_name_key UNIQUE (alias_name);



ALTER TABLE ONLY public.technology_alias
    ADD CONSTRAINT technology_alias_pkey PRIMARY KEY (alias_id);



ALTER TABLE ONLY public.technology_dictionary
    ADD CONSTRAINT technology_dictionary_pkey PRIMARY KEY (tech_id);



CREATE INDEX esco_skills_preferred_label_idx ON public."ESCO_Skills" USING btree (preferred_label);



CREATE INDEX technology_alias_alias_name_idx ON public.technology_alias USING btree (alias_name);



CREATE INDEX technology_dictionary_canonical_name_idx ON public.technology_dictionary USING btree (canonical_name);



ALTER TABLE ONLY public.technology_alias
    ADD CONSTRAINT technology_alias_tech_id_fkey FOREIGN KEY (tech_id) REFERENCES public.technology_dictionary(tech_id) ON DELETE CASCADE;



